// CV slew: Asymmetric rise and fall applied to a square LFO before it controls audio gain.
// Audition composition of public Rust primitives; not an instrument parity claim.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  oscillator as oscillatorDefinition,
  lfo as lfoDefinition,
  slewControl as slewControlDefinition,
  modulatedGain as modulatedGainDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    oscillator_waveform: {
      "path": "/primitives/cv-slew/node/0",
      "label": "Waveform",
      "group": "Oscillator",
      "min": 0,
      "max": 4,
      "default": 0,
      "choices": [
        "Sine",
        "Saw",
        "Square",
        "Triangle",
        "Blend"
      ]
    },
    oscillator_frequency: {
      "path": "/primitives/cv-slew/node/1",
      "label": "Frequency",
      "group": "Oscillator",
      "min": 20,
      "max": 16000,
      "default": 220
    },
    oscillator_level: {
      "path": "/primitives/cv-slew/node/2",
      "label": "Level",
      "group": "Oscillator",
      "min": 0,
      "max": 1,
      "default": 0.16
    },
    lfo_waveform: {
      "path": "/primitives/cv-slew/lfo/0",
      "label": "Waveform",
      "group": "LFO",
      "min": 0,
      "max": 2,
      "default": 2,
      "choices": [
        "Sine",
        "Triangle",
        "Square"
      ]
    },
    lfo_rate: {
      "path": "/primitives/cv-slew/lfo/1",
      "label": "Rate",
      "group": "LFO",
      "min": 0.05,
      "max": 20,
      "default": 2
    },
    slew_riseSamples: {
      "path": "/primitives/cv-slew/slew/0",
      "label": "Rise samples",
      "group": "CV slew",
      "min": 1,
      "max": 1024,
      "default": 800
    },
    slew_fallSamples: {
      "path": "/primitives/cv-slew/slew/1",
      "label": "Fall samples",
      "group": "CV slew",
      "min": 1,
      "max": 1024,
      "default": 400
    },
    gain_base: {
      "path": "/primitives/cv-slew/gain/0",
      "label": "Base",
      "group": "CV gain",
      "min": 0,
      "max": 2,
      "default": 0.5
    },
    gain_depth: {
      "path": "/primitives/cv-slew/gain/1",
      "label": "Depth",
      "group": "CV gain",
      "min": -2,
      "max": 2,
      "default": 0.4
    },
  };

  // Audio inputs and outputs — generated sound; no audio input is needed.
  const graph = createGraphWorkspace().setInputSource('none');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const oscillator = graph.add(oscillatorDefinition.type, {"id":4});
  graph.registerInstance('/primitives/cv-slew/node', oscillator);
  oscillator.parameter('waveform').expose(controls.oscillator_waveform);
  oscillator.parameter('frequency').expose(controls.oscillator_frequency);
  oscillator.parameter('level').expose(controls.oscillator_level);

  const lfo = graph.add(lfoDefinition.type, {"id":5});
  graph.registerInstance('/primitives/cv-slew/lfo', lfo);
  lfo.parameter('waveform').expose(controls.lfo_waveform);
  lfo.parameter('rate').expose(controls.lfo_rate);

  const slew = graph.add(slewControlDefinition.type, {"id":6});
  graph.registerInstance('/primitives/cv-slew/slew', slew);
  slew.parameter('riseSamples').expose(controls.slew_riseSamples);
  slew.parameter('fallSamples').expose(controls.slew_fallSamples);

  const gain = graph.add(modulatedGainDefinition.type, {"id":7});
  graph.registerInstance('/primitives/cv-slew/gain', gain);
  gain.parameter('base').expose(controls.gain_base);
  gain.parameter('depth').expose(controls.gain_depth);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(oscillator.output('out'), gain.input('audio'));
  graph.connect(lfo.output('out'), slew.input('cv'));
  graph.connect(slew.output('out'), gain.input('cv'));
  graph.connect(gain.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.oscillator_waveform,
    controls.oscillator_frequency,
    controls.oscillator_level,
    controls.lfo_waveform,
    controls.lfo_rate,
    controls.slew_riseSamples,
    controls.slew_fallSamples,
    controls.gain_base,
    controls.gain_depth
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
